     1	package br.com.marealta.report;
     2	
     3	import br.com.marealta.domain.Reservation;
     4	
     5	import java.util.ArrayList;
     6	import java.util.List;
     7	
     8	/** Esqueleto: título, cabeçalho, linhas e total. As subclasses só dizem o conteúdo. */
     9	public abstract class CsvReport<P> implements Report {
    10	    static final String POUSADA = "Pousada Maré Alta";
    11	
    12	    /** Conteúdo de um relatório, sem formatação. */
    13	    protected record Table(List<String> header, List<List<String>> rows, List<String> total) {}
    14	
    15	    protected abstract P parse(String period);
    16	
    17	    protected abstract Table build(P period, List<Reservation> reservations);
    18	
    19	    @Override
    20	    public final String generate(String period, List<Reservation> reservations) {
    21	        if (period == null) throw new InvalidPeriodException("Parâmetro '" + parameter() + "' é obrigatório");
    22	        P parsed = parse(period);
    23	        Table table = build(parsed, reservations);
    24	        List<List<String>> lines = new ArrayList<>();
    25	        lines.add(List.of(POUSADA, name(), period));
    26	        lines.add(table.header());
    27	        lines.addAll(table.rows());
    28	        lines.add(table.total());
    29	        StringBuilder sb = new StringBuilder();
    30	        for (List<String> line : lines) sb.append(String.join(",", line)).append('\n');
    31	        return sb.toString();
    32	    }
    33	}
