=== report/MonthlyCsvReport.java
     1	package br.com.marealta.report;
     2	
     3	import br.com.marealta.domain.Reservation;
     4	
     5	import java.time.YearMonth;
     6	import java.time.format.DateTimeParseException;
     7	import java.util.Comparator;
     8	import java.util.List;
     9	
    10	/** Base dos relatórios de um mês, sobre as reservas que começam nele. */
    11	abstract class MonthlyCsvReport extends CsvReport<YearMonth> {
    12	    @Override
    13	    public String parameter() { return "month"; }
    14	
    15	    @Override
    16	    protected YearMonth parse(String period) {
    17	        if (!period.matches("\\d{4}-\\d{2}")) throw new InvalidPeriodException("Mês inválido: " + period);
    18	        try {
    19	            return YearMonth.parse(period);
    20	        } catch (DateTimeParseException e) {
    21	            throw new InvalidPeriodException("Mês inválido: " + period);
    22	        }
    23	    }
    24	
    25	    /** Reservas que começam no mês, por data de entrada e depois por número. */
    26	    protected static List<Reservation> startingIn(YearMonth month, List<Reservation> all) {
    27	        return all.stream()
    28	                .filter(r -> YearMonth.from(r.checkInDate()).equals(month))
    29	                .sorted(Comparator.comparing(Reservation::checkInDate).thenComparingInt(Reservation::id))
    30	                .toList();
    31	    }
    32	
    33	    /** As que deixaram dinheiro com a pousada (base do financeiro e dos planos). */
    34	    protected static List<Reservation> retainingMoney(YearMonth month, List<Reservation> all) {
    35	        return startingIn(month, all).stream().filter(r -> r.retained().signum() > 0).toList();
    36	    }
    37	}
=== report/OccupancyReport.java
     1	package br.com.marealta.report;
     2	
     3	import br.com.marealta.domain.Reservation;
     4	import br.com.marealta.service.RoomCatalog;
     5	
     6	import java.time.LocalDate;
     7	import java.time.format.DateTimeParseException;
     8	import java.util.Comparator;
     9	import java.util.List;
    10	
    11	public class OccupancyReport extends CsvReport<LocalDate> {
    12	    private final RoomCatalog rooms;
    13	
    14	    public OccupancyReport(RoomCatalog rooms) { this.rooms = rooms; }
    15	
    16	    @Override public String name() { return "occupancy"; }
    17	
    18	    @Override public String parameter() { return "date"; }
    19	
    20	    @Override
    21	    protected LocalDate parse(String period) {
    22	        try {
    23	            return LocalDate.parse(period);
    24	        } catch (DateTimeParseException e) {
    25	            throw new InvalidPeriodException("Data inválida: " + period);
    26	        }
    27	    }
    28	
    29	    @Override
    30	    protected Table build(LocalDate night, List<Reservation> all) {
    31	        List<Reservation> occupying = all.stream()
    32	                .filter(r -> r.isPaid() && r.occupiesNight(night))
    33	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()).thenComparingInt(Reservation::id))
    34	                .toList();
    35	        List<List<String>> rows = occupying.stream().map(r -> List.of(
    36	                String.valueOf(r.room().number()), r.room().type().name(), String.valueOf(r.id()),
    37	                r.checkInDate().toString(), r.checkOutDate().toString())).toList();
    38	        long occupiedRooms = occupying.stream().map(r -> r.room().number()).distinct().count();
    39	        return new Table(List.of("room", "type", "reservation", "check_in", "check_out"), rows,
    40	                List.of("total", occupiedRooms + "/" + rooms.all().size()));
    41	    }
    42	}
