     1	package br.com.marealta.report;
     2	
     3	import br.com.marealta.domain.Money;
     4	import br.com.marealta.domain.RatePlan;
     5	import br.com.marealta.domain.Reservation;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.YearMonth;
     9	import java.util.ArrayList;
    10	import java.util.List;
    11	
    12	public class RatePlanReport extends MonthlyCsvReport {
    13	    @Override public String name() { return "rate-plans"; }
    14	
    15	    @Override
    16	    protected Table build(YearMonth month, List<Reservation> all) {
    17	        List<Reservation> included = retainingMoney(month, all);
    18	        List<List<String>> rows = new ArrayList<>();
    19	        int count = 0;
    20	        BigDecimal sum = Money.ZERO;
    21	        for (RatePlan plan : RatePlan.values()) {
    22	            List<Reservation> ofPlan = included.stream().filter(r -> r.ratePlan() == plan).toList();
    23	            BigDecimal amount = ofPlan.stream().map(Reservation::retained).reduce(Money.ZERO, BigDecimal::add);
    24	            rows.add(List.of(plan.name(), String.valueOf(ofPlan.size()), Money.plain(amount)));
    25	            count += ofPlan.size();
    26	            sum = sum.add(amount);
    27	        }
    28	        return new Table(List.of("rate_plan", "reservations", "amount"), rows,
    29	                List.of("total", String.valueOf(count), Money.plain(sum)));
    30	    }
    31	}
