     8	/** Taxa da prefeitura por hóspede por noite. O valor muda todo ano: é só trocar aqui. */
     9	public class TourismTaxPolicy {
    10	    public static final BigDecimal CURRENT_RATE = Money.of("4.50");
    11	
    12	    private final BigDecimal ratePerGuestNight;
    13	
    14	    public TourismTaxPolicy(BigDecimal ratePerGuestNight) { this.ratePerGuestNight = ratePerGuestNight; }
    15	
    16	    public static TourismTaxPolicy current() { return new TourismTaxPolicy(CURRENT_RATE); }
    17	
    18	    public BigDecimal taxFor(Reservation r) {
    19	        return Money.round(ratePerGuestNight.multiply(BigDecimal.valueOf((long) r.guests() * r.nights())));
    20	    }
    21	}
