     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.BusinessException;
     4	import br.com.marealta.domain.ErrorCode;
     5	import br.com.marealta.domain.RatePlan;
     6	import br.com.marealta.service.BookingRequest;
     7	import com.fasterxml.jackson.databind.JsonNode;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	
    10	import java.time.LocalDate;
    11	import java.time.format.DateTimeParseException;
    12	
    13	/** Valida o corpo do POST /reservations. */
    14	final class BookingParser {
    15	    private static final ObjectMapper MAPPER = new ObjectMapper();
    16	
    17	    private BookingParser() {}
    18	
    19	    static BookingRequest parse(String body) {
    20	        JsonNode json;
    21	        try {
    22	            json = MAPPER.readTree(body);
    23	        } catch (Exception e) {
    24	            throw invalid("Corpo não é um JSON válido");
    25	        }
    26	        if (json == null || !json.isObject()) throw invalid("Corpo deve ser um objeto JSON");
    27	
    28	        int roomNumber = integer(json, "roomNumber");
    29	        int guests = integer(json, "guests");
    30	        LocalDate checkIn = date(json, "checkIn");
    31	        LocalDate checkOut = date(json, "checkOut");
    32	        RatePlan plan;
    33	        try {
    34	            plan = RatePlan.valueOf(text(json, "ratePlan"));
    35	        } catch (IllegalArgumentException e) {
    36	            throw invalid("ratePlan inválido");
    37	        }
    38	        if (!checkOut.isAfter(checkIn)) throw invalid("A saída deve ser depois da entrada");
    39	        if (guests < 1) throw invalid("Deve haver ao menos um hóspede");
    40	        return new BookingRequest(roomNumber, text(json, "guestName"), text(json, "guestEmail"),
    41	                text(json, "guestCpf"), checkIn, checkOut, guests, plan);
    42	    }
    43	
    44	    private static String text(JsonNode json, String field) {
    45	        JsonNode node = json.get(field);
    46	        if (node == null || !node.isTextual() || node.asText().isBlank()) throw invalid("Campo obrigatório: " + field);
    47	        return node.asText();
    48	    }
    49	
    50	    private static int integer(JsonNode json, String field) {
    51	        JsonNode node = json.get(field);
    52	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    53	            throw invalid("Campo obrigatório (inteiro): " + field);
    54	        }
    55	        return node.asInt();
    56	    }
    57	
    58	    private static LocalDate date(JsonNode json, String field) {
    59	        try {
    60	            return LocalDate.parse(text(json, field));
    61	        } catch (DateTimeParseException e) {
    62	            throw invalid("Data inválida: " + field);
    63	        }
    64	    }
    65	
    66	    private static BusinessException invalid(String message) {
    67	        return new BusinessException(ErrorCode.INVALID_REQUEST, message);
    68	    }
    69	}
