    29	    private static String formatCpf(String cpf) {
    30	        if (cpf.matches("\\d{11}")) {
    31	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    32	        }
    33	        return cpf;
    34	    }
    35	}
