     9	import java.util.List;
    10	
    11	public class ReservationService {
    12	    private static final String EMAIL = "EMAIL";
    13	
    14	    private final RoomCatalog rooms;
    15	    private final ReservationRepository repository;
    16	    private final MessageSender sender;
    17	
    18	    public ReservationService(RoomCatalog rooms, ReservationRepository repository, MessageSender sender) {
    19	        this.rooms = rooms;
    20	        this.repository = repository;
    21	        this.sender = sender;
    22	    }
    23	
    24	    public synchronized Reservation create(BookingRequest req) {
    25	        if (req.guests() < 1 || !req.checkOut().isAfter(req.checkIn())) {
    26	            throw new BusinessException(ErrorCode.INVALID_REQUEST, "Datas ou número de hóspedes inválidos");
    27	        }
    28	        Room room = rooms.find(req.roomNumber())
    29	                .orElseThrow(() -> new BusinessException(ErrorCode.ROOM_NOT_FOUND, "Quarto inexistente"));
    30	        if (req.guests() > room.capacity()) {
    31	            throw new BusinessException(ErrorCode.CAPACITY_EXCEEDED, "O quarto comporta até " + room.capacity() + " pessoas");
    32	        }
    33	        boolean taken = repository.all().stream()
    34	                .filter(r -> r.room().number() == room.number() && r.status() != ReservationStatus.CANCELLED)
    35	                .anyMatch(r -> r.overlaps(req.checkIn(), req.checkOut()));
    36	        if (taken) {
    37	            throw new BusinessException(ErrorCode.ROOM_UNAVAILABLE, "Quarto já reservado em alguma das noites");
    38	        }
    39	        Reservation reservation = new Reservation(repository.nextId(), room, req.guestName(), req.guestEmail(),
    40	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), req.ratePlan());
    41	        repository.save(reservation);
    42	        return reservation;
    43	    }
    44	
    45	    public synchronized Reservation get(int id) {
    46	        return repository.find(id)
    47	                .orElseThrow(() -> new BusinessException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva inexistente"));
    48	    }
    49	
    50	    public synchronized Reservation confirm(int id) {
    51	        Reservation r = get(id);
    52	        r.confirm();
    53	        sender.send(EMAIL, r.guestEmail(), "Reserva confirmada - Pousada Maré Alta", confirmationBody(r));
    54	        return r;
    55	    }
    56	
    57	    public synchronized Reservation cancel(int id) {
    58	        Reservation r = get(id);
    59	        r.cancel();
    60	        return r;
    61	    }
    62	
    63	    public synchronized Reservation checkIn(int id) {
    64	        Reservation r = get(id);
    65	        r.checkIn();
    66	        return r;
    67	    }
    68	
    69	    public synchronized Receipt checkOut(int id) {
    70	        Reservation r = get(id);
    71	        r.checkOut();
    72	        return Receipt.of(r);
    73	    }
    74	
    75	    /** Segunda via: só para reserva paga. */
    76	    public synchronized Receipt receipt(int id) {
    77	        Reservation r = get(id);
    78	        if (!r.isPaid()) {
    79	            throw new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED, "Comprovante só existe para reserva paga");
    80	        }
    81	        return Receipt.of(r);
    82	    }
    83	
    84	    public synchronized List<Reservation> all() {
    85	        return repository.all();
    86	    }
    87	
    88	    private String confirmationBody(Reservation r) {
    89	        return "Olá, " + r.guestName() + "!\n\n"
    90	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    91	                + ReceiptFormatter.format(r) + "\n\n"
    92	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    93	                + "Até breve!";
    94	    }
    95	}
