    33	        this.checkIn = checkIn;
    34	        this.checkOut = checkOut;
    35	        this.guests = guests;
    36	        this.ratePlan = ratePlan;
    37	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    38	        BigDecimal sum = Money.ZERO;
    39	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    40	            sum = sum.add(Season.nightPrice(room, night));
    41	        }
    42	        this.subtotal = Money.round(sum);
    43	        this.discount = ratePlan.discount(subtotal);
    44	        this.total = Money.round(subtotal.subtract(discount));
    45	    }
