    47	    /** Duas reservas disputam o quarto se alguma noite coincide. */
    48	    public boolean overlaps(LocalDate otherIn, LocalDate otherOut) {
    49	        return checkIn.isBefore(otherOut) && otherIn.isBefore(checkOut);
    50	    }
    51	
    52	    public boolean occupiesNight(LocalDate night) {
    53	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
    54	    }
