    73	        require(status == ReservationStatus.PENDING || status == ReservationStatus.CONFIRMED,
    74	                "Só é possível cancelar uma reserva pendente ou confirmada");
    75	        refund = ratePlan.refund(amountPaid);
    76	        status = ReservationStatus.CANCELLED;
