     8	public final class ReceiptFormatter {
     9	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    10	
    11	    private ReceiptFormatter() {}
    12	
    13	    public static String format(Reservation r) {
    14	        StringBuilder sb = new StringBuilder();
    15	        sb.append("Comprovante de reserva nº ").append(r.id()).append('\n');
    16	        sb.append("Hóspede: ").append(r.guestName()).append(" (CPF ").append(formatCpf(r.guestCpf())).append(")\n");
    17	        sb.append("Quarto: ").append(r.room().number()).append(" (").append(r.room().type()).append(")\n");
    18	        sb.append("Entrada: ").append(r.checkInDate().format(DATE))
    19	                .append(" | Saída: ").append(r.checkOutDate().format(DATE))
    20	                .append(" | ").append(r.nights()).append(r.nights() == 1 ? " diária" : " diárias").append('\n');
    21	        sb.append("Diárias: ").append(Money.brl(r.subtotal())).append('\n');
    22	        if (r.discount().signum() > 0) {
    23	            sb.append("Desconto: ").append(Money.brl(r.discount())).append('\n');
    24	        }
    25	        sb.append("Total: ").append(Money.brl(r.total()));
    26	        return sb.toString();
    27	    }
    28	
    29	    private static String formatCpf(String cpf) {
    30	        if (cpf.matches("\\d{11}")) {
    31	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
    32	        }
    33	        return cpf;
    34	    }
    35	}
