    33	    static String booking(int room, String in, String out, int guests, String plan) {
    34	        return """
    35	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@x.com","guestCpf":"11122233344",
    36	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, in, out, guests, plan);
    37	    }
