    39	    @Test
    40	    void fullFlowAndReports() throws Exception {
    41	        var created = call("POST", "/reservations", booking(101, "2027-07-10", "2027-07-12", 2, "STANDARD"));
    42	        assertEquals(201, created.statusCode());
    43	        assertTrue(created.body().contains("\"total\":599.76"), created.body());
    44	
    45	        assertEquals(409, call("POST", "/reservations", booking(101, "2027-07-11", "2027-07-13", 1, "STANDARD")).statusCode());
    46	        assertEquals(422, call("POST", "/reservations", booking(101, "2027-08-11", "2027-08-13", 3, "STANDARD")).statusCode());
    47	        assertEquals(400, call("POST", "/reservations", "nope").statusCode());
    48	        assertEquals(409, call("GET", "/reservations/1/document", null).statusCode());
    49	
    50	        assertEquals(200, call("POST", "/reservations/1/confirmation", null).statusCode());
    51	        var messages = call("GET", "/messages", null).body();
    52	        assertTrue(messages.contains("Reserva confirmada - Pousada Maré Alta"), messages);
    53	
    54	        var occupancy = call("GET", "/reports/occupancy?date=2027-07-10", null);
    55	        assertEquals("Pousada Maré Alta,occupancy,2027-07-10\n"
    56	                + "room,type,reservation,check_in,check_out\n"
    57	                + "101,STANDARD,1,2027-07-10,2027-07-12\n"
    58	                + "total,1/5\n", occupancy.body());
    59	        assertTrue(occupancy.headers().firstValue("content-type").orElse("").toLowerCase().contains("text/csv"));
    60	
    61	        assertEquals("Pousada Maré Alta,tourism-tax,2027-07\n"
    62	                + "reservation,room,check_in,check_out,guests,nights,tax\n"
    63	                + "1,101,2027-07-10,2027-07-12,2,2,18.00\n"
    64	                + "total,18.00\n", call("GET", "/reports/tourism-tax?month=2027-07", null).body());
    65	
    66	        assertEquals("Pousada Maré Alta,rate-plans,2027-07\n"
    67	                + "rate_plan,reservations,amount\n"
    68	                + "STANDARD,1,599.76\n"
    69	                + "NON_REFUNDABLE,0,0.00\n"
    70	                + "total,1,599.76\n", call("GET", "/reports/rate-plans?month=2027-07", null).body());
    71	
    72	        assertEquals(400, call("GET", "/reports/revenue?month=2027-13", null).statusCode());
    73	
    74	        assertEquals(200, call("POST", "/reservations/1/check-in", null).statusCode());
    75	        var out = call("POST", "/reservations/1/check-out", null);
    76	        assertTrue(out.body().contains("\"title\":\"Comprovante de reserva\""), out.body());
    77	        assertEquals(409, call("POST", "/reservations/1/cancellation", null).statusCode());
    78	        assertEquals(404, call("GET", "/reservations/99", null).statusCode());
    79	    }
